    Bug 2065695 - Fix msgKey<->UID mapping in nsImapService::StreamMessage(). r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D322810

diff --git a/mailnews/imap/src/nsImapProtocol.cpp b/mailnews/imap/src/nsImapProtocol.cpp
index 1659cfe9238..d23f6850858 100644
--- a/mailnews/imap/src/nsImapProtocol.cpp
+++ b/mailnews/imap/src/nsImapProtocol.cpp
@@ -9686,9 +9686,18 @@ bool nsImapMockChannel::ReadFromLocalCache() {
     return false;
   }
   // we want to create a file channel and read the msg from there.
-  // TODO: UID->nsMsgKey mapping
-  // https://bugzilla.mozilla.org/show_bug.cgi?id=1806770
-  nsMsgKey msgKey = strtoul(messageIdString.get(), nullptr, 10);
+
+  // Need the message key to get to offline copy.
+  ImapUid uid = strtoul(messageIdString.get(), nullptr, 10);
+  nsCOMPtr<nsIMsgDatabase> db;
+  rv = folder->GetMsgDatabase(getter_AddRefs(db));
+  NS_ENSURE_SUCCESS(rv, false);
+
+  nsMsgKey msgKey = MsgKeyFromUid(db, uid).unwrapOr(nsMsgKey_None);
+  if (msgKey == nsMsgKey_None) {
+    NS_WARNING("UID lookup failed");
+    return false;
+  }
   nsCOMPtr<nsIMsgDBHdr> hdr;
   rv = folder->GetMessageHeader(msgKey, getter_AddRefs(hdr));
   NS_ENSURE_SUCCESS(rv, false);
diff --git a/mailnews/imap/src/nsImapService.cpp b/mailnews/imap/src/nsImapService.cpp
index 56ac6360fbf..f35c9c20700 100644
--- a/mailnews/imap/src/nsImapService.cpp
+++ b/mailnews/imap/src/nsImapService.cpp
@@ -908,9 +908,15 @@ NS_IMETHODIMP nsImapService::StreamMessage(
   // We need to add the fetch command here for the cache lookup to behave
   // correctly
   nsAutoCString additionalHeader(aAdditionalHeader);
-  nsAutoCString msgKey;
-  msgKey.AppendInt(key);
-  rv = AddImapFetchToUrl(mailnewsurl, folder, msgKey, additionalHeader);
+
+  nsCOMPtr<nsIMsgDatabase> db;
+  MOZ_TRY(folder->GetMsgDatabase(getter_AddRefs(db)));
+
+  ImapUid uid = MOZ_TRY(UidFromMsgKey(db, key));
+  nsAutoCString msgIds;
+  msgIds.AppendInt(uid);
+
+  rv = AddImapFetchToUrl(mailnewsurl, folder, msgIds, additionalHeader);
   NS_ENSURE_SUCCESS(rv, rv);

   nsCOMPtr<nsIMsgIncomingServer> aMsgIncomingServer;
